pyautogui.FAILSAFE = False

def windows():
    try:
        return pyautogui.getAllWindows()
    except Exception:
        return []

def activate(match):
    for w in windows():
        title = (w.title or '')
        if match.lower() in title.lower():
            try:
                w.activate()
                time.sleep(0.5)
            except Exception:
                pass
            return True
    return False

